inline int g_devicesBuilt{ 0 };

class PoweredDevice
{
public:
    explicit PoweredDevice(int watts) : m_watts{ watts } { ++g_devicesBuilt; }
    int watts() const { return m_watts; }

private:
    int m_watts{};
};

class Scanner : public PoweredDevice
{
public:
    explicit Scanner(int watts) : PoweredDevice{ watts } {}
};

class Printer : public PoweredDevice
{
public:
    explicit Printer(int watts) : PoweredDevice{ watts } {}
};

class Copier : public Scanner, public Printer
{
public:
    explicit Copier(int watts) : Scanner{ watts }, Printer{ watts } {}
};

solution.solution.cpp:
inline int g_devicesBuilt{ 0 };

class PoweredDevice
{
public:
    explicit PoweredDevice(int watts) : m_watts{ watts } { ++g_devicesBuilt; }
    int watts() const { return m_watts; }

private:
    int m_watts{};
};

class Scanner : virtual public PoweredDevice
{
public:
    explicit Scanner(int watts) : PoweredDevice{ watts } {}
};

class Printer : virtual public PoweredDevice
{
public:
    explicit Printer(int watts) : PoweredDevice{ watts } {}
};

class Copier : public Scanner, public Printer
{
public:
    explicit Copier(int watts) : PoweredDevice{ watts }, Scanner{ watts }, Printer{ watts } {}
};

unitTests:
TEST("a copier has exactly one powered device inside") { g_devicesBuilt = 0; const Copier c{ 300 }; CHECK_EQ(g_devicesBuilt, 1); }
TEST("so asking for its watts is no longer ambiguous") { const Copier c{ 450 }; CHECK_EQ(c.watts(), 450); const PoweredDevice& base{ c }; CHECK_EQ(base.watts(), 450); }
TEST("scanners and printers still work on their own") { g_devicesBuilt = 0; const Scanner s{ 20 }; const Printer p{ 60 }; CHECK_EQ(g_devicesBuilt, 2); CHECK_EQ(s.watts(), 20); CHECK_EQ(p.watts(), 60); }

